"use client"

import * as React from "react"

// Pestle — a hero for an invented neighbourhood pharmacy that handles repeat
// prescriptions. The page comes up as one sequence on one clock:
//   1. a count runs while the two capsule pictures and the fonts load;
//   2. the capsule, closed, drops into the room and lands on the floor;
//   3. it pulls open: the cap slides off the base and floats up behind the line;
//   4. "Refills." rises letter by letter between the two halves;
//   5. the nav, the copy and the button arrive last.
// The two halves are the same two elements from the first frame to the last.
// Any click, key or wheel skips to the end; reduced motion shows the end at once.
// Light comes from a window at the upper left, so shadows fall to the right.

const SITE = "https://kedhar-components.pages.dev/pestle-pharmacy-hero/"

export interface PestlePharmacyHeroProps {
  /** Any definite CSS length. Percentages need a sized parent. */
  height?: string
  ctaLabel?: string
  ctaHref?: string
  /** Play the loading intro (default) or start on the finished hero. */
  intro?: boolean
  className?: string
}

// #region timeline
/** Measured on the two pictures, as fractions of each picture's box. */
export const CAP = { pivot: [0.0957, 0.7199], sleeve: 130 / 760, length: 722.5 / 760, turn: 28.07 }
export const BASE = { mouth: [786 / 983, 287 / 486] }
/** Phase windows in ms after the gate opens (pictures loaded and the count at 100). */
export const T = {
  countMin: 600,
  countFade: [0, 240],
  drop: [0, 540],
  settle: [540, 740],
  split: [680, 1380],
  clipEnd: 0.42,
  swap: 0.62,
  word: [1100, 1740],
  letter: 62,
  letterDur: 520,
  ui: [1580, 2280],
  uiStep: 110,
  uiDur: 480,
}
export const TOTAL = T.ui[1]

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x)
const win = (t: number, a: number, b: number) => clamp01((t - a) / (b - a))
export const easeOut = (x: number) => 1 - Math.pow(1 - x, 3)
export const easeInOut = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2)
export const easeIn = (x: number) => x * x

export interface Geo {
  W: number; H: number; F: number
  bl: number; bt: number; bw: number; bh: number
  cl: number; ct: number; cw: number; ch: number
}
export interface Pose {
  base: { x: number; y: number; r: number; ox: number; oy: number }
  cap: { x: number; y: number; r: number; ox: number; oy: number; clip: number; front: boolean }
  contact: number; contactWide: number; capShadow: number
  count: number
  letters: number[]
  ui: number[]
}

/** The whole scene at time t (ms after the gate opens). Offsets are px from each part's resting place. */
export function pose(t: number, g: Geo, letterCount = 8, uiCount = 3): Pose {
  const bo = { x: BASE.mouth[0] * g.bw, y: BASE.mouth[1] * g.bh }
  const co = { x: CAP.pivot[0] * g.cw, y: CAP.pivot[1] * g.ch }
  const mouth = { x: g.bl + bo.x, y: g.bt + bo.y } // base mouth, at rest
  const pivotRest = { x: g.cl + co.x, y: g.ct + co.y }
  const sleeve = CAP.sleeve * g.cw
  const capLen = (CAP.length - CAP.sleeve) * g.cw

  // 1–2: the closed capsule falls in from above the frame and lands with a small bounce
  const lift = mouth.y + 0.45 * g.bh // just above the top edge
  const d = win(t, T.drop[0], T.drop[1])
  const s = win(t, T.settle[0], T.settle[1])
  const bounce = Math.sin(Math.PI * s) * 0.06 * g.F * (1 - s)
  const y = -lift * (1 - easeIn(d)) - (d >= 1 ? bounce : 0)
  const r = -16 * (1 - easeOut(d)) + (d >= 1 ? 2.2 * Math.sin(Math.PI * s) * (1 - s) : 0)
  const rad = (r * Math.PI) / 180
  const W = { x: mouth.x, y: mouth.y + y } // base mouth, now

  // 3: the split
  const q = easeInOut(win(t, T.split[0], T.split[1]))
  const closedPivot = { x: W.x - sleeve * Math.cos(rad), y: W.y - sleeve * Math.sin(rad) }
  const ctrl = { x: Math.max(closedPivot.x, pivotRest.x) + 0.25 * g.cw, y: closedPivot.y - 0.05 * g.F }
  const bez = (a: number, b: number, c: number) => (1 - q) * (1 - q) * a + 2 * (1 - q) * q * b + q * q * c
  const pv = { x: bez(closedPivot.x, ctrl.x, pivotRest.x), y: bez(closedPivot.y, ctrl.y, pivotRest.y) }
  const capR = (r + CAP.turn) * (1 - q)
  const clip = q >= T.clipEnd ? 0 : sleeve * (1 - q / T.clipEnd)

  const near = clamp01(1 + y / (0.9 * g.F)) // 0 high in the air, 1 on the floor
  const letters = Array.from({ length: letterCount }, (_, i) => easeOut(win(t, T.word[0] + i * T.letter, T.word[0] + i * T.letter + T.letterDur)))
  const ui = Array.from({ length: uiCount }, (_, i) => easeOut(win(t, T.ui[0] + i * T.uiStep, T.ui[0] + i * T.uiStep + T.uiDur)))
  return {
    base: { x: W.x - mouth.x, y: W.y - mouth.y, r, ox: bo.x, oy: bo.y },
    cap: { x: pv.x - pivotRest.x, y: pv.y - pivotRest.y, r: capR, ox: co.x, oy: co.y, clip, front: q < T.swap },
    contact: near * near,
    contactWide: capLen * (1 - q),
    capShadow: q,
    count: 1 - easeOut(win(t, T.countFade[0], T.countFade[1])),
    letters,
    ui,
  }
}

/** The count shown while the gate is closed: time-led, but it holds at 92 until the pictures are in. */
export function countAt(elapsed: number, loaded: boolean): number {
  const p = clamp01(elapsed / T.countMin)
  return Math.floor(100 * (loaded ? p : Math.min(p, 0.92)))
}

/** Clip polygon (px, in the cap's own box) that hides everything closer than `k` to its open end. */
export function capClip(k: number, cw: number, ch: number): string {
  if (k <= 0) return "none"
  const th = (-CAP.turn * Math.PI) / 180
  const u = { x: Math.cos(th), y: Math.sin(th) } // open end -> dome
  const n = { x: -u.y, y: u.x }
  const p = { x: CAP.pivot[0] * cw + u.x * k, y: CAP.pivot[1] * ch + u.y * k }
  const L = 4 * (cw + ch)
  const pts = [
    [p.x + n.x * L, p.y + n.y * L],
    [p.x - n.x * L, p.y - n.y * L],
    [p.x - n.x * L + u.x * L, p.y - n.y * L + u.y * L],
    [p.x + n.x * L + u.x * L, p.y + n.y * L + u.y * L],
  ]
  return "polygon(" + pts.map(([x, y]) => x.toFixed(1) + "px " + y.toFixed(1) + "px").join(",") + ")"
}
// #endregion

const FONT_SERIF = "data:font/woff2;base64,"
const FONT_SANS = "data:font/woff2;base64,"
const FONT_SANS_BOLD = "data:font/woff2;base64,"

const CSS =
  "@font-face{font-family:PphSerif;font-weight:400;font-style:normal;font-display:block;src:url(" + FONT_SERIF + ") format('woff2')}" +
  "@font-face{font-family:PphSans;font-weight:400;font-style:normal;font-display:block;src:url(" + FONT_SANS + ") format('woff2')}" +
  "@font-face{font-family:PphSans;font-weight:700;font-style:normal;font-display:block;src:url(" + FONT_SANS_BOLD + ") format('woff2')}" +
  ".pph-root{--pph-wall:#dce5e0;--pph-floor:#c7d5cd;--pph-light:rgba(255,255,255,.75);--pph-green:#0e4b36;--pph-text:#22362d;--pph-on:#f3f7f4;--pph-shade:9,32,24;position:relative;width:100%;overflow:hidden;container-type:size;container-name:pph;isolation:isolate;background:var(--pph-wall);color:var(--pph-text);font-family:PphSans,ui-sans-serif,system-ui,sans-serif}" +
  ".dark .pph-root{--pph-wall:#16211d;--pph-floor:#0f1814;--pph-light:rgba(190,230,210,.10);--pph-green:#bfe3cf;--pph-text:#d5e2db;--pph-on:#0e2a20;--pph-shade:0,0,0}" +
  ".pph-in{position:absolute;inset:0;--g:clamp(20px,4cqw,72px);--nav:clamp(64px,8cqh,84px);--F:min(calc((100cqw - 2 * var(--g)) * 0.86 / 3.6),calc((100cqh - var(--nav) - 190px) / 1.6));--rk:1.75;--wk:1.39;--floor:calc(100cqh - 0.1 * var(--F));--rw:calc(var(--rk) * var(--F));--rh:calc(var(--rw) * 0.4944);--rx:calc(var(--g) + 0.6 * var(--F));--base:calc(var(--floor) - var(--rh) + 0.2 * var(--F));--wt:calc(var(--base) - 0.84 * var(--F));--ww:calc(var(--wk) * var(--F));--wh:calc(var(--ww) * 0.8974);--wx:calc(var(--rx) + var(--rw) - 0.1 * var(--ww));--wy:max(calc(var(--nav) + 12px),calc(var(--wt) + 0.3 * var(--F) - var(--wh)))}" +
  ".pph-room{position:absolute;inset:0;z-index:0;background:radial-gradient(60% 75% at 6% 0%,var(--pph-light),transparent 70%),linear-gradient(to bottom,var(--pph-wall) 0,var(--pph-wall) calc(var(--floor) - 0.45 * var(--F)),var(--pph-floor) calc(var(--floor) - 0.05 * var(--F)),var(--pph-floor) 100%)}" +
  ".pph-nav{position:absolute;left:var(--g);right:var(--g);top:0;height:var(--nav);z-index:6;display:flex;align-items:center;justify-content:space-between;gap:16px}" +
  ".pph-logo{color:var(--pph-green);text-decoration:none;font-family:PphSerif,ui-serif,Georgia,serif;font-size:clamp(22px,1.75cqw,28px);line-height:1}" +
  ".pph-links{display:flex;gap:clamp(16px,2.4cqw,36px)}" +
  ".pph-links a{color:var(--pph-text);text-decoration:none;font-size:clamp(14px,1.05cqw,16px);line-height:1.2;padding:6px 0;background:linear-gradient(currentColor,currentColor) 0 100%/0 1px no-repeat;transition:background-size .25s ease}" +
  ".pph-links a:hover{background-size:100% 1px}" +
  ".pph-root a:focus-visible{outline:2px solid var(--pph-green);outline-offset:4px;border-radius:2px}" +
  ".pph-copy{position:absolute;left:var(--g);top:calc(var(--nav) + 0.12 * var(--F));width:min(26em,calc(var(--wx) - var(--g) - 0.3 * var(--F)));z-index:5;font-size:clamp(15px,calc(var(--F) * 0.058),19px)}" +
  ".pph-copy p{margin:0;line-height:1.5;max-width:26em}" +
  ".pph-cta{display:inline-flex;align-items:center;justify-content:center;margin-top:1.3em;min-height:52px;padding:0 1.5em;border-radius:999px;background:var(--pph-green);color:var(--pph-on);text-decoration:none;font-weight:700;font-size:1em;line-height:1;transition:transform .2s ease,box-shadow .2s ease}" +
  ".pph-cta:hover{transform:translateY(-2px);box-shadow:0 12px 22px -14px rgba(var(--pph-shade),.9)}" +
  ".pph-word{position:absolute;left:var(--g);top:var(--wt);margin:0;z-index:3;font-family:PphSerif,ui-serif,Georgia,serif;font-weight:400;font-size:var(--F);line-height:1;letter-spacing:-0.02em;color:var(--pph-green);white-space:nowrap}" +
  ".pph-l{display:inline-block}" +
  ".pph-part{position:absolute;margin:0;pointer-events:none}" +
  ".pph-part img{position:absolute;inset:0;display:block;width:100%;height:100%;max-width:none;object-fit:contain}" +
  ".pph-cap{left:var(--wx);top:var(--wy);width:var(--ww);height:var(--wh);z-index:2}" +
  ".pph-base{left:var(--rx);top:calc(var(--floor) - var(--rh));width:var(--rw);height:var(--rh);z-index:4}" +
  ".pph-shadow{position:absolute;pointer-events:none;z-index:1}" +
  ".pph-contact{left:calc(var(--rx) + 0.03 * var(--rw));width:calc(0.98 * var(--rw));top:calc(var(--floor) - 0.035 * var(--F));height:calc(0.07 * var(--F));background:radial-gradient(closest-side,rgba(var(--pph-shade),.62),rgba(var(--pph-shade),.28) 55%,rgba(var(--pph-shade),0))}" +
  ".pph-cast{left:calc(var(--rx) + 0.12 * var(--rw));width:calc(1.08 * var(--rw));top:calc(var(--floor) - 0.06 * var(--F));height:calc(0.2 * var(--F));background:radial-gradient(closest-side,rgba(var(--pph-shade),.2),rgba(var(--pph-shade),0))}" +
  ".pph-capshadow{left:calc(var(--wx) + 0.3 * var(--ww));width:calc(0.85 * var(--ww));top:calc(var(--floor) - 0.05 * var(--F));height:calc(0.13 * var(--F));background:radial-gradient(closest-side,rgba(var(--pph-shade),.16),rgba(var(--pph-shade),0))}" +
  ".pph-count{position:absolute;left:0;right:0;top:50%;z-index:7;margin:0;text-align:center;font-family:PphSerif,ui-serif,Georgia,serif;font-size:clamp(28px,3cqw,44px);line-height:1;color:var(--pph-green);font-variant-numeric:tabular-nums;pointer-events:none}" +
  ".pph-root[data-intro=wait] .pph-l,.pph-root[data-intro=wait] .pph-ui{opacity:0}" +
  ".pph-root[data-intro=wait] .pph-part{transform:translateY(-200cqh)}" +
  ".pph-root[data-intro=wait] .pph-shadow{opacity:0}" +
  ".pph-root[data-intro=done] .pph-count{display:none}" +
  "@container pph (max-width:700px){" +
  ".pph-in{--g:20px;--nav:64px;--F:calc((100cqw - 40px) / 3.6);--rk:3.2;--wk:2.54;--rx:var(--g);--wx:calc(100cqw - 0.92 * var(--ww));--shift:max(0px,calc((100cqh - 250px - var(--nav) - 0.64 * var(--F) - var(--wh) - var(--rh)) / 2));--wt:calc(var(--nav) + 0.15 * var(--F) + var(--shift));--wy:calc(var(--wt) + 0.49 * var(--F));--floor:calc(var(--wy) + var(--wh) - 0.15 * var(--F) + var(--rh))}" +
  ".pph-copy{right:var(--g);width:auto;top:auto;bottom:var(--g);font-size:16px}" +
  ".pph-links{gap:14px}" +
  ".pph-links a{font-size:14px}" +
  "}" +
  "@media (prefers-reduced-motion: reduce){.pph-cta,.pph-links a{transition:none}.pph-cta:hover{transform:none}}"

const WORD = "Refills."

export function PestlePharmacyHero({
  height = "100svh",
  ctaLabel = "Set up my refills",
  ctaHref = "#refills",
  intro = true,
  className = "",
}: PestlePharmacyHeroProps) {
  const rootRef = React.useRef(null as HTMLElement | null)

  React.useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const q = (s: string) => root.querySelector(s) as HTMLElement
    const inner = q(".pph-in"), base = q(".pph-base"), cap = q(".pph-cap"), word = q(".pph-word")
    const count = q(".pph-count"), contact = q(".pph-contact"), cast = q(".pph-cast"), capShadow = q(".pph-capshadow")
    const letters = Array.from(root.querySelectorAll(".pph-l")) as HTMLElement[]
    const ui = Array.from(root.querySelectorAll(".pph-ui")) as HTMLElement[]
    const imgs = Array.from(root.querySelectorAll("img"))

    const finish = () => {
      for (const el of [base, cap, contact, cast, capShadow, ...letters, ...ui]) {
        el.style.transform = ""; el.style.opacity = ""; el.style.clipPath = ""; el.style.zIndex = ""; el.style.transformOrigin = ""; el.style.width = ""
      }
      root.dataset.intro = "done"
    }
    const reduce = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches
    if (!intro || reduce) { finish(); return }

    let raf = 0, gone = false, loaded = false, gateAt = -1, skip = false
    const start = performance.now()
    const fonts = (document as Document & { fonts?: FontFaceSet }).fonts
    Promise.all([
      ...imgs.map((im) => (im.complete && im.naturalWidth > 0 ? Promise.resolve() : new Promise((r) => { im.addEventListener("load", r, { once: true }); im.addEventListener("error", r, { once: true }) }))),
      fonts && fonts.load ? fonts.load("400 100px PphSerif").catch(() => undefined) : Promise.resolve(),
    ]).then(() => { loaded = true })
    const failsafe = window.setTimeout(() => { loaded = true }, 6000)
    const onSkip = () => { skip = true }
    const events = ["pointerdown", "keydown", "wheel", "touchstart"]
    for (const e of events) root.addEventListener(e, onSkip, { passive: true })

    const apply = (t: number) => {
      const F = parseFloat(getComputedStyle(word).fontSize)
      const g: Geo = {
        W: inner.clientWidth, H: inner.clientHeight, F,
        bl: base.offsetLeft, bt: base.offsetTop, bw: base.offsetWidth, bh: base.offsetHeight,
        cl: cap.offsetLeft, ct: cap.offsetTop, cw: cap.offsetWidth, ch: cap.offsetHeight,
      }
      const p = pose(t, g, letters.length, ui.length)
      // a part at rest carries no transform at all, so its last moving frame and the finished hero are the same picture
      const move = (el: HTMLElement, x: number, y: number, r: number, ox: number, oy: number) => {
        if (Math.abs(x) < 0.05 && Math.abs(y) < 0.05 && Math.abs(r) < 0.005) { el.style.transform = ""; el.style.transformOrigin = ""; return }
        el.style.transformOrigin = ox + "px " + oy + "px"
        el.style.transform = "translate(" + x.toFixed(2) + "px," + y.toFixed(2) + "px) rotate(" + r.toFixed(3) + "deg)"
      }
      move(base, p.base.x, p.base.y, p.base.r, p.base.ox, p.base.oy)
      move(cap, p.cap.x, p.cap.y, p.cap.r, p.cap.ox, p.cap.oy)
      const clip = capClip(p.cap.clip, g.cw, g.ch)
      cap.style.clipPath = clip === "none" ? "" : clip
      cap.style.zIndex = p.cap.front ? "5" : ""
      contact.style.opacity = p.contact >= 0.999 ? "" : String(p.contact)
      contact.style.width = p.contactWide < 0.05 ? "" : "calc(0.98 * var(--rw) + " + p.contactWide.toFixed(1) + "px)"
      cast.style.opacity = p.contact >= 0.999 ? "" : String(p.contact)
      capShadow.style.opacity = p.capShadow >= 0.999 ? "" : String(p.capShadow)
      count.style.opacity = String(p.count)
      // a part that has settled drops its inline style at once, so text is never left on a sub-pixel offset
      const place = (el: HTMLElement, o: number, dy: number) => {
        if (o >= 0.999 && Math.abs(dy) < 0.05) { el.style.opacity = ""; el.style.transform = ""; return }
        el.style.opacity = String(o); el.style.transform = "translateY(" + dy.toFixed(2) + "px)"
      }
      letters.forEach((el, i) => { const v = p.letters[i]; place(el, Math.min(1, v * 1.6), (1 - v) * 0.32 * F) })
      ui.forEach((el, i) => { const v = p.ui[i]; place(el, v, (1 - v) * 14) })
    }

    const tick = (now: number) => {
      if (gone) return
      const elapsed = now - start
      if (gateAt < 0) {
        if (skip) loaded = true
        count.textContent = countAt(elapsed, loaded) + "%"
        if (loaded && (skip || elapsed >= T.countMin)) { gateAt = now; root.dataset.intro = "play"; count.textContent = "100%" }
      }
      if (gateAt >= 0) {
        const t = skip ? TOTAL : now - gateAt
        if (t >= TOTAL) { finish(); return }
        apply(t)
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => {
      gone = true; cancelAnimationFrame(raf); window.clearTimeout(failsafe)
      for (const e of events) root.removeEventListener(e, onSkip)
    }
  }, [intro])

  return (
    <section ref={rootRef} className={"pph-root " + className} style={{ height }} data-intro="wait" aria-labelledby="pph-title">
      <style>{CSS}</style>
      <div className="pph-in">
        <div className="pph-room" aria-hidden="true" />
        <header className="pph-nav pph-ui">
          <a className="pph-logo" href="#">Pestle</a>
          <nav className="pph-links" aria-label="Main">
            <a href="#how">How it works</a>
            <a href="#prices">Prices</a>
            <a href="#help">Help</a>
          </nav>
        </header>

        <div className="pph-copy">
          <p className="pph-ui">We order your repeat prescription from your GP, a pharmacist checks it, and it arrives at your door within two days. No queue, no phone calls.</p>
          <a className="pph-cta pph-ui" href={ctaHref}>{ctaLabel}</a>
        </div>

        <span className="pph-shadow pph-capshadow" aria-hidden="true" />
        <span className="pph-shadow pph-cast" aria-hidden="true" />
        <span className="pph-shadow pph-contact" aria-hidden="true" />
        <figure className="pph-part pph-cap" aria-hidden="true">
          <img src={SITE + "white.webp"} alt="" width={760} height={682} decoding="async" />
        </figure>
        <h1 id="pph-title" className="pph-word" aria-label={WORD}>
          {Array.from(WORD).map((c, i) => <span key={i} className="pph-l" aria-hidden="true">{c}</span>)}
        </h1>
        <figure className="pph-part pph-base">
          <img src={SITE + "red.webp"} alt="An opened capsule: the red base lies on the floor and the white cap hovers above it" width={983} height={486} decoding="async" />
        </figure>
        <p className="pph-count" aria-hidden="true">0%</p>
      </div>
    </section>
  )
}

export default PestlePharmacyHero
